import{_ as p,a0 as o,w as d,s as h,I as e,x as a,a1 as n,A as t,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"iWant：一个去中心化的点对点共享文件的命令行工具 | LCTT x X-CMD","titleTemplate":false,"description":"iWant：一个去中心化的点对点共享文件的命令行工具 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"iWant：一个去中心化的点对点共享文件的命令行工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"iWant：一个去中心化的点对点共享文件的命令行工具 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20170710 iWant - The Decentralized Peer To Peer File Sharing Commandline Application","title":"iWant：一个去中心化的点对点共享文件的命令行工具","tag":"201904","desc":""},"relativePath":"201904/20170710 iWant - The Decentralized Peer To Peer File Sharing Commandline Application.md","filePath":"[post].md"}'),r={name:"201904/20170710 iWant - The Decentralized Peer To Peer File Sharing Commandline Application.md"};function g(c,i,k,b,u,f){const s=o("Link");return d(),h("div",null,[i[23]||(i[23]=e("h1",{id:"iwant-一个去中心化的点对点共享文件的命令行工具",tabindex:"-1"},[a("iWant：一个去中心化的点对点共享文件的命令行工具 "),e("a",{class:"header-anchor",href:"#iwant-一个去中心化的点对点共享文件的命令行工具","aria-label":"Permalink to “iWant：一个去中心化的点对点共享文件的命令行工具”"},"​")],-1)),i[24]||(i[24]=e("p",null,[e("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/07/p2p-720x340.jpg",alt:""})],-1)),e("p",null,[i[2]||(i[2]=a("不久之前，我们编写了一个指南，内容是一个文件共享实用程序，名为 ",-1)),n(s,{href:"https://www.ostechnix.com/easy-fast-way-share-files-internet-command-line/"},{default:t(()=>[...i[0]||(i[0]=[a("transfer.sh",-1)])]),_:1}),i[3]||(i[3]=a("，它是一个免费的 Web 服务，允许你在 Internet 上轻松快速地共享文件，还有 ",-1)),n(s,{href:"https://www.ostechnix.com/psitransfer-simple-open-source-self-hosted-file-sharing-solution/"},{default:t(()=>[...i[1]||(i[1]=[a("PSiTransfer",-1)])]),_:1}),i[4]||(i[4]=a("，一个简单的开源自托管文件共享解决方案。今天，我们将看到另一个名为 “iWant” 的文件共享实用程序。它是一个基于命令行的自由开源的去中心化点对点文件共享应用程序。",-1))]),i[25]||(i[25]=l('<p>你可能想知道，它与其它文件共享应用程序有什么不同？以下是 iWant 的一些突出特点。</p><ul><li>它是一个命令行应用程序。这意味着你不需要消耗内存来加载 GUI 实用程序。你只需要一个终端。</li><li>它是去中心化的。这意味着你的数据不会在任何中心位置存储。因此，不会因为中心点失败而失败。</li><li>iWant 允许中断下载，你可以在以后随时恢复。你不需要从头开始下载，它会从你停止的位置恢复下载。</li><li>共享目录中文件所作的任何更改（如删除、添加、修改）都会立即反映在网络中。</li><li>就像种子一样，iWant 从多个节点下载文件。如果任何节点离开群组或未能响应，它将继续从另一个节点下载。</li><li>它是跨平台的，因此你可以在 GNU/Linux、MS Windows 或者 Mac OS X 中使用它。</li></ul><h3 id="安装-iwant" tabindex="-1">安装 iWant <a class="header-anchor" href="#安装-iwant" aria-label="Permalink to “安装 iWant”">​</a></h3><p>iWant 可以使用 PIP 包管理器轻松安装。确保你在 Linux 发行版中安装了 pip。如果尚未安装，参考以下指南。</p>',4)),e("p",null,[n(s,{href:"https://www.ostechnix.com/manage-python-packages-using-pip/"},{default:t(()=>[...i[5]||(i[5]=[a("如何使用 Pip 管理 Python 包",-1)])]),_:1})]),i[26]||(i[26]=l(`<p>安装 pip 后，确保你有以下依赖项：</p><ul><li>libffi-dev</li><li>libssl-dev</li></ul><p>比如说，在 Ubuntu 上，你可以使用以下命令安装这些依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install libffi-dev libssl-dev</span></span></code></pre></div><p>安装完所有依赖项后，使用以下命令安装 iWant：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pip install iwant</span></span></code></pre></div><p>现在我们的系统中已经有了 iWant，让我们来看看如何使用它来通过网络传输文件。</p><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>首先，使用以下命令启动 iWant 服务器：</p><p>（LCTT 译注：虽然这个软件是叫 iWant，但是其命令名为 <code>iwanto</code>，另外这个软件至少一年没有更新了。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto start</span></span></code></pre></div><p>第一次启动时，iWant 会询问想要分享和下载文件夹的位置，所以需要输入两个文件夹的位置。然后，选择要使用的网卡。</p><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Shared/Download folder details looks empty..</span></span>
<span class="line"><span>Note: Shared and Download folder cannot be the same</span></span>
<span class="line"><span>SHARED FOLDER(absolute path):/home/sk/myshare</span></span>
<span class="line"><span>DOWNLOAD FOLDER(absolute path):/home/sk/mydownloads</span></span>
<span class="line"><span>Network interface available</span></span>
<span class="line"><span>1. lo =&gt; 127.0.0.1</span></span>
<span class="line"><span>2. enp0s3 =&gt; 192.168.43.2</span></span>
<span class="line"><span>Enter index of the interface:2</span></span>
<span class="line"><span>now scanning /home/sk/myshare</span></span>
<span class="line"><span>[Adding] /home/sk/myshare 0.0</span></span>
<span class="line"><span>Updating Leader 56f6d5e8-654e-11e7-93c8-08002712f8c1</span></span>
<span class="line"><span>[Adding] /home/sk/myshare 0.0</span></span>
<span class="line"><span>connecting to 192.168.43.2:1235 for hashdump</span></span></code></pre></div><p>如果你看到类似上面的输出，你可以立即开始使用 iWant 了。</p><p>同样，在网络中的所有系统上启动 iWant 服务，指定有效的分享和下载文件夹的位置，并选择合适的网卡。</p><p>iWant 服务将继续在当前终端窗口中运行，直到你按下 <code>CTRL+C</code> 退出为止。你需要打开一个新选项卡或新的终端窗口来使用 iWant。</p><p>iWant 的用法非常简单，它的命令很少，如下所示。</p><ul><li><code>iwanto start</code> – 启动 iWant 服务。</li><li><code>iwanto search &lt;name&gt;</code> – 查找文件。</li><li><code>iwanto download &lt;hash&gt;</code> – 下载一个文件。</li><li><code>iwanto share &lt;path&gt;</code> – 更改共享文件夹的位置。</li><li><code>iwanto download to &lt;destination&gt;</code> – 更改下载文件夹位置。</li><li><code>iwanto view config</code> – 查看共享和下载文件夹。</li><li><code>iwanto –version</code> – 显示 iWant 版本。</li><li><code>iwanto -h</code> – 显示帮助信息。</li></ul><p>让我向你展示一些例子。</p><h4 id="查找文件" tabindex="-1">查找文件 <a class="header-anchor" href="#查找文件" aria-label="Permalink to “查找文件”">​</a></h4><p>要查找一个文件，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto search &lt;filename&gt;</span></span></code></pre></div><p>请注意，你无需指定确切的名称。</p><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto search command</span></span></code></pre></div><p>上面的命令将搜索包含 “command” 字符串的所有文件。</p><p>我的 Ubuntu 系统会输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Filename Size Checksum</span></span>
<span class="line"><span>------------------------------------------- ------- --------------------------------</span></span>
<span class="line"><span>/home/sk/myshare/THE LINUX COMMAND LINE.pdf 3.85757 efded6cc6f34a3d107c67c2300459911</span></span></code></pre></div><h4 id="下载文件" tabindex="-1">下载文件 <a class="header-anchor" href="#下载文件" aria-label="Permalink to “下载文件”">​</a></h4><p>你可以在你的网络上的任何系统下载文件。要下载文件，只需提供文件的哈希（校验和），如下所示。你可以使用 <code>iwanto search</code> 命令获取共享的哈希值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto download efded6cc6f34a3d107c67c2300459911</span></span></code></pre></div><p>文件将保存在你的下载位置，在本文中是 <code>/home/sk/mydownloads/</code> 位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Filename: /home/sk/mydownloads/THE LINUX COMMAND LINE.pdf</span></span>
<span class="line"><span>Size: 3.857569 MB</span></span></code></pre></div><h4 id="查看配置" tabindex="-1">查看配置 <a class="header-anchor" href="#查看配置" aria-label="Permalink to “查看配置”">​</a></h4><p>要查看配置，例如共享和下载文件夹的位置，运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto view config</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Shared folder:/home/sk/myshare</span></span>
<span class="line"><span>Download folder:/home/sk/mydownloads</span></span></code></pre></div><h4 id="更改共享和下载文件夹的位置" tabindex="-1">更改共享和下载文件夹的位置 <a class="header-anchor" href="#更改共享和下载文件夹的位置" aria-label="Permalink to “更改共享和下载文件夹的位置”">​</a></h4><p>你可以更改共享文件夹和下载文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto share /home/sk/ostechnix</span></span></code></pre></div><p>现在，共享位置已更改为 <code>/home/sk/ostechnix</code>。</p><p>同样，你可以使用以下命令更改下载位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto download to /home/sk/Downloads</span></span></code></pre></div><p>要查看所做的更改，运行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ iwanto view config</span></span></code></pre></div><h4 id="停止-iwant" tabindex="-1">停止 iWant <a class="header-anchor" href="#停止-iwant" aria-label="Permalink to “停止 iWant”">​</a></h4><p>一旦你不想用 iWant 了，可以按下 <code>CTRL+C</code> 退出。</p><p>如果它不起作用，那可能是由于防火墙或你的路由器不支持多播。你可以在 <code>~/.iwant/.iwant.log</code> 文件中查看所有日志。有关更多详细信息，参阅最后提供的项目的 GitHub 页面。</p><p>差不多就是全部了。希望这个工具有所帮助。下次我会带着另一个有趣的指南再次来到这里。</p><p>干杯！</p><h3 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to “资源”">​</a></h3>`,53)),e("p",null,[i[7]||(i[7]=a("-",-1)),n(s,{href:"https://github.com/nirvik/iWant"},{default:t(()=>[...i[6]||(i[6]=[a("iWant GitHub",-1)])]),_:1})]),i[27]||(i[27]=e("hr",null,null,-1)),e("p",null,[i[9]||(i[9]=a("via: ",-1)),n(s,{href:"https://www.ostechnix.com/iwant-decentralized-peer-peer-file-sharing-commandline-application/"},{default:t(()=>[...i[8]||(i[8]=[a("https://www.ostechnix.com/iwant-decentralized-peer-peer-file-sharing-commandline-application/",-1)])]),_:1})]),e("p",null,[i[14]||(i[14]=a("作者：",-1)),n(s,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...i[10]||(i[10]=[a("SK",-1)])]),_:1}),i[15]||(i[15]=a(" 选题：",-1)),n(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[11]||(i[11]=[a("lujun9972",-1)])]),_:1}),i[16]||(i[16]=a(" 译者：",-1)),n(s,{href:"https://github.com/MjSeven"},{default:t(()=>[...i[12]||(i[12]=[a("MjSeven",-1)])]),_:1}),i[17]||(i[17]=a(" 校对：",-1)),n(s,{href:"https://github.com/wxy"},{default:t(()=>[...i[13]||(i[13]=[a("wxy",-1)])]),_:1})]),e("p",null,[i[20]||(i[20]=a("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[18]||(i[18]=[a("LCTT",-1)])]),_:1}),i[21]||(i[21]=a(" 原创编译，",-1)),n(s,{href:"https://linux.cn/"},{default:t(()=>[...i[19]||(i[19]=[a("Linux中国",-1)])]),_:1}),i[22]||(i[22]=a(" 荣誉推出",-1))])])}const C=p(r,[["render",g]]);export{y as __pageData,C as default};
